import{_ as e,I as r,f as o,i as l}from"./chunks/framework.CzIb_Ns1.js";const _=JSON.parse('{"title":"修复","description":"","frontmatter":{},"headers":[],"relativePath":"OS/ColorOS/fix.md","filePath":"OS/ColorOS/fix.md"}'),i={name:"OS/ColorOS/fix.md"};function t(s,a,p,d,h,n){return r(),o("div",null,[...a[0]||(a[0]=[l('<h1 id="修复" tabindex="-1">修复 <a class="header-anchor" href="#修复" aria-label="Permalink to “修复”">​</a></h1><p>适用于ColorOS15~16.1</p><h2 id="" tabindex="-1"><a class="header-anchor" href="#" aria-label="Permalink to “”">​</a></h2><h3 id="_1-开机卡小布" tabindex="-1">1.开机卡小布 <a class="header-anchor" href="#_1-开机卡小布" aria-label="Permalink to “1.开机卡小布”">​</a></h3><p>odm/etc/build.prop里面添加 import /odm/build.prop import /odm/etc/${ro.boot.prjname}/build.gsi.prop import /odm/etc/${ro.boot.prjname}/build.${ro.boot.flag}.prop import /mnt/vendor/my_product/etc/${ro.boot.prjname}/build.${ro.boot.flag}.prop 再将原包odm/build.prop添加进原机同目录</p><h3 id="_2-挖孔修复-修复流体云位置" tabindex="-1">2.挖孔修复（修复流体云位置） <a class="header-anchor" href="#_2-挖孔修复-修复流体云位置" aria-label="Permalink to “2.挖孔修复（修复流体云位置）”">​</a></h3><p>在原机系统中打开开发者设置 然后找到指针位置 挖孔的上下左右都量一遍按照这样的格式填 ro.oplus.display.screenhole.positon=左x,上y,右x,下y 例如我的小米13数值就是505,29:575,99 505对应挖孔左边x轴其他同理</p><h3 id="_3-挖孔遮罩修复-这边提供两种方法" tabindex="-1">3.挖孔遮罩修复 这边提供两种方法 <a class="header-anchor" href="#_3-挖孔遮罩修复-这边提供两种方法" aria-label="Permalink to “3.挖孔遮罩修复 这边提供两种方法”">​</a></h3><p>如果你是屏幕边缘没有坏点的机子 按照如下 打开system/my_product/etc/permissions/oplus.product.display_features把其中带corner的feature删掉 如果你是屏幕上有坏点的机子 如:小米13 打开先找到原机的product/etc/overlay/devicesoverlay.apk 然后打开/res/drawable/我们可以看见里面会有遮罩 然后我们打开ps或者什么画图软件 把上下左右四个角的遮罩全部按照正方形的截出来 中间的挖孔也是 然后找到 system/my_product/overlay/oplus_framework_res_overlay.display.product.xxxxx.apk 把你截图出来的四个角和挖孔替换 这边解释一下名字oplus_rc_bottom_left就是左下角 oplus_rc_cutout就是挖孔</p><h3 id="_4-状态栏高度修复" tabindex="-1">4.状态栏高度修复 <a class="header-anchor" href="#_4-状态栏高度修复" aria-label="Permalink to “4.状态栏高度修复”">​</a></h3><p>system/my_product/overlay/android_framework_res_overlay.display.product.xxxxx.apk里面的resources照着product/overlay/DevicesAndroidOverlay.apk里面的数值改</p><h3 id="_5-dpi修复" tabindex="-1">5.dpi修复 <a class="header-anchor" href="#_5-dpi修复" aria-label="Permalink to “5.dpi修复”">​</a></h3><p>system/my_product/build.prop里面的 ro.sf.lcd_density改成原机对应</p><h3 id="_6-音量键位置" tabindex="-1">6.音量键位置 <a class="header-anchor" href="#_6-音量键位置" aria-label="Permalink to “6.音量键位置”">​</a></h3><p>system/my_product/persist.oplus.software.audio.right_volume_key如果你的音量键在右边就true 左边就false</p><h3 id="_7-相机参数" tabindex="-1">7.相机参数 <a class="header-anchor" href="#_7-相机参数" aria-label="Permalink to “7.相机参数”">​</a></h3><p>odm/build.prop ro.vendor.oplus.camera.frontCamSize=前置 ro.vendor.oplus.camera.backCamSize=后置</p><h3 id="_8-屏幕大小" tabindex="-1">8.屏幕大小 <a class="header-anchor" href="#_8-屏幕大小" aria-label="Permalink to “8.屏幕大小”">​</a></h3><p>odm/build.prop ro.oplus.display.screenSizeInches.primary=原机</p><h3 id="_9-机型显示" tabindex="-1">9.机型显示 <a class="header-anchor" href="#_9-机型显示" aria-label="Permalink to “9.机型显示”">​</a></h3><p>ro.vendor.oplus.market.name=中文名 ro.vendor.oplus.market.enname=英文名</p><h3 id="_10-处理器参数" tabindex="-1">10.处理器参数: <a class="header-anchor" href="#_10-处理器参数" aria-label="Permalink to “10.处理器参数:”">​</a></h3><p>ro.build.device_family=op+代号 ro.product.oplus.cpuinfo=代号</p><h3 id="_11-电源键延迟" tabindex="-1">11.电源键延迟 <a class="header-anchor" href="#_11-电源键延迟" aria-label="Permalink to “11.电源键延迟”">​</a></h3><p>补hal不多赘述 自行解决</p><h3 id="_12-电压异常-电池容量" tabindex="-1">12.电压异常 电池容量 <a class="header-anchor" href="#_12-电压异常-电池容量" aria-label="Permalink to “12.电压异常 电池容量”">​</a></h3><p>原包odm/etc/power_profile文件夹扔原机 打开里面的power_profile.xml搜battery.capacity 数值改成原机</p><h3 id="_13-振动" tabindex="-1">13.振动 <a class="header-anchor" href="#_13-振动" aria-label="Permalink to “13.振动”">​</a></h3><p>补lib不多赘述</p><h3 id="_14-双击亮屏" tabindex="-1">14.双击亮屏 <a class="header-anchor" href="#_14-双击亮屏" aria-label="Permalink to “14.双击亮屏”">​</a></h3><h3 id="_15-快充修复感谢-luluz" tabindex="-1">15.快充修复感谢@luluz <a class="header-anchor" href="#_15-快充修复感谢-luluz" aria-label="Permalink to “15.快充修复感谢@luluz”">​</a></h3><p>这里补一个链接:<a href="https://www.123684.com/s/nzgGjv-uCwWA" target="_blank" rel="noreferrer">https://www.123684.com/s/nzgGjv-uCwWA</a></p><h3 id="_16-抬腕亮屏-lazyboness" tabindex="-1">16.抬腕亮屏@lazyboness <a class="header-anchor" href="#_16-抬腕亮屏-lazyboness" aria-label="Permalink to “16.抬腕亮屏@lazyboness”">​</a></h3><p>换lazybones改好的apk就行不多赘述 下载链接:<a href="https://www.123684.com/s/nzgGjv-UCwWA" target="_blank" rel="noreferrer">https://www.123684.com/s/nzgGjv-UCwWA</a></p><h3 id="_18-微信扫一扫修复" tabindex="-1">18.微信扫一扫修复 <a class="header-anchor" href="#_18-微信扫一扫修复" aria-label="Permalink to “18.微信扫一扫修复”">​</a></h3><p>删system_ext/etc/sys_camera_optimize_config.xml</p><h3 id="_19-屏幕色温异常" tabindex="-1">19.屏幕色温异常 <a class="header-anchor" href="#_19-屏幕色温异常" aria-label="Permalink to “19.屏幕色温异常”">​</a></h3><p>删my_product/etc/permissions/oplus.product.display_system_features.xml</p><h3 id="_20-内存扩展-猫羽今天吃什么-开源项目" tabindex="-1">20.内存扩展@猫羽今天吃什么 开源项目 <a class="header-anchor" href="#_20-内存扩展-猫羽今天吃什么-开源项目" aria-label="Permalink to “20.内存扩展@猫羽今天吃什么 开源项目”">​</a></h3>',39)])])}const m=e(i,[["render",t]]);export{_ as __pageData,m as default};
